/* HELP translations. German, Spanish and French remain automatic editorial drafts. */
(()=>{'use strict';
const translations={"it":{"Support":"Supporto","Quick start":"Primi passi","Troubleshooting":"Risoluzione problemi","Under the hood":"Come funziona","Layers":"Livelli","Params":"Parametri","Parameters":"Parametri","Color":"Colore","Library":"Libreria","Performance":"Prestazioni","Time":"Tempo","Mapping":"Mappatura","REPORT AN ISSUE":"SEGNALA UN PROBLEMA","Report an issue or get in touch.":"Segnala un problema o contattami.","Having trouble with INDEX HTML BRIDGE? Get in touch.":"Problemi con INDEX HTML BRIDGE? Scrivimi.","Having trouble with CONSEQUENCE OF TIME? Get in touch.":"Problemi con CONSEQUENCE OF TIME? Scrivimi.","Send some audio":"Invia un segnale audio","Shape the audio-responsive signal A.":"Modella il segnale A che risponde all’audio.","Audio source":"Sorgente audio","Use the main track input or select an external sidechain. Check routing when nothing moves.":"Usa l’ingresso della traccia oppure una sidechain esterna. Se non si muove nulla, verifica il routing.","Adjust incoming level before the signal is analyzed.":"Regola il livello in ingresso prima dell’analisi.","Set how quickly signal A reacts to increasing and decreasing audio intensity. These controls do not modify B Attack, Hold or Decay.":"Regola la velocità di risposta di A all’aumento e alla diminuzione dell’intensità audio. Non modifica Attack, Hold o Decay di B.","Adjust the amount applied to normalized A. It is not the contact threshold used by the time engine.":"Regola la quantità applicata ad A normalizzato. Non è la soglia di contatto del motore temporale.","Build a time-driven signal B from recognized contact.":"Costruisci il segnale temporale B a partire dal contatto riconosciuto.","Contact threshold":"Soglia di contatto","Choose BEATS (musical tempo) or TIME (elapsed time) as the accumulation window; the two modes retain separate values.":"Scegli BEATS (tempo musicale) o TIME (tempo trascorso) come finestra di accumulo; le due modalità conservano valori separati.","Set initial signal level and range of movement.":"Imposta il livello iniziale del segnale e la sua escursione.","Attack smooths growth, Hold keeps the value after contact is lost, Decay returns B toward zero.":"Attack smussa la crescita, Hold mantiene il valore dopo la perdita di contatto, Decay riporta B verso zero.","Pure time evolution. Time Amount has no effect in CLEAN.":"Evoluzione temporale pura. Time Amount non ha effetto in CLEAN.","Changes movement range in response to intensity.":"Modifica l’escursione in risposta all’intensità.","Changes accumulation speed in response to intensity.":"Modifica la velocità di accumulo in risposta all’intensità.","Adds signal-dependent irregular fluctuations.":"Aggiunge oscillazioni irregolari dipendenti dal segnale.","May produce a descending positive curve, not negative output; transitions can be abrupt.":"Può generare una curva positiva discendente, non un’uscita negativa; le transizioni possono essere brusche.","Can pause time progress when intensity meets its condition.":"Può sospendere l’avanzamento temporale quando l’intensità soddisfa la condizione.","Quantizes the time signal into discrete steps.":"Quantizza il segnale temporale in passi discreti.","Combines speed changes and irregular fluctuations. Time Amount adjusts each active behavior, not the basic B Depth.":"Combina variazioni di velocità e oscillazioni irregolari. Time Amount regola ogni comportamento attivo, non B Depth di base.","Mod works as relative modulation around a parameter base value. Remote takes exclusive control of its destination. These are native Ableton behaviors.":"Mod modula relativamente al valore di base del parametro. Remote ne assume il controllo esclusivo. Sono comportamenti nativi di Ableton.","Save & Reload":"Salvataggio e riapertura","After mapping, verify actual modulation after saving and reopening the Live Set — not only that the destination name persists.":"Dopo la mappatura, salva e riapri il Live Set e verifica che la modulazione funzioni davvero, non soltanto che sia presente il nome della destinazione.","Distribution note":"Nota sulla distribuzione","Choose a separate source for audio analysis.":"Scegli una sorgente separata per l’analisi audio.","Main audio":"Audio principale","External sidechain":"Sidechain esterna","Common checks for signal, timing and mapping.":"Controlli comuni su segnale, tempo e mappatura.","No signal movement":"Nessun movimento del segnale","Confirm that audio is present, inspect source and routing, increase Gain as appropriate, and check the contact threshold and B Depth.":"Verifica che l’audio sia presente, controlla sorgente e routing, regola Gain e verifica soglia di contatto e B Depth.","A moves but B does not":"A si muove ma B no","Check the threshold and Tolerance, the Window, Growth, B Start/Depth and whether sufficient contact time has accumulated.":"Controlla soglia, Tolerance, Window, Growth e B Start/Depth, e verifica che si accumuli abbastanza tempo di contatto.","Mapping looks static":"La mappatura sembra ferma","In Mod mode, the base knob may stay at its set value while modulation operates. Check the destination response, not only the knob position.":"In modalità Mod, il knob base può rimanere fermo mentre la modulazione agisce. Verifica la destinazione, non solo la posizione del knob.","A: amplitude response":"A: risposta all’ampiezza","The envelope follower translates the level of the input signal into a continuous normalized modulation output.":"L’envelope follower trasforma il livello d’ingresso in un’uscita di modulazione continua e normalizzata.","B: duration response":"B: risposta alla durata","Contact recognition drives a separate time engine. Window, Growth, Accel, Hold, Decay and Behavior change the shape of B.":"Il rilevamento del contatto controlla un motore temporale separato. Window, Growth, Accel, Hold, Decay e Behavior plasmano B.","Audio transparency":"Trasparenza audio","Shape it":"Modellalo","Open PARAMETERS, COLORS & BLEND and MIDI MAPPING in any combination.":"Apri PARAMETERS, COLORS & BLEND e MIDI MAPPING nella combinazione che preferisci.","Render live":"Renderizza live","RENDER opens the external Chromium compositor. Your five Layers are combined there.":"RENDER apre il compositore Chromium esterno, nel quale vengono combinati i cinque Layer.","Five independent visual slots, composed from L1 upward. Effects process only what sits below them.":"Cinque slot visual indipendenti, composti a partire da L1. Gli effetti elaborano solo i livelli sottostanti.","One editor, five layers":"Un editor, cinque livelli","Tool loading":"Caricamento tool","Generator vs effect":"Generatore o effetto","Remembered per layer":"Memoria per livello","Native Live parameters":"Parametri Live nativi","Reset & defaults":"Reset e valori predefiniti","Effective values":"Valori effettivi","Automation stays yours":"L’automazione resta tua","Colors & Blend":"Colori e blend","Effect Layers do not use generator blend in the same way: their shader processes the lower composite directly.":"Gli Effect Layer non usano il blend come i generatori: lo shader elabora direttamente la composizione sottostante.","MIDI Mapping":"Mappatura MIDI","Map NOTE or CC directly onto P01–P12 with amount and envelope/smoothing controls.":"Mappa NOTE o CC direttamente su P01–P12 con quantità e controlli di inviluppo/smoothing.","Status":"Stato","Selected tool":"Tool selezionato","Requirements":"Requisiti","Live output":"Output live","Live Render Performance":"Prestazioni del rendering live","Automatic panel":"Pannello automatico","Read the monitor":"Leggi il monitor","Same view, different quality":"Stessa inquadratura, qualità diversa","The useful failure boundaries, current limitations and what not to expect from this build.":"I punti di errore più utili, i limiti attuali e cosa non aspettarsi da questa build.","Browser or missing resources":"Browser o risorse mancanti","Only if you care: how Max, Node and Chromium divide the work.":"Per chi vuole approfondire: come Max, Node e Chromium si dividono il lavoro.","No Jitter renderer":"Nessun renderer Jitter","INDEX HTML stays browser-native. The fundamental split is simple: Max decides what happens; the browser decides how to draw it.":"INDEX HTML rimane nativo del browser. La distinzione è semplice: Max decide cosa accade; il browser decide come disegnarlo.","Open one Layer editor at a time. Layer visibility is independent from whether its editor is open.":"Apri un editor di Layer alla volta. La visibilità di ciascun Layer è indipendente dall’apertura del suo editor.","Choosing a tool in the dropdown only selects it. Press LOAD to use the selection. A new LOAD restores manifest defaults. Keep tools/ and the complete device folder together; local INDEX_TOOL RC2 and legacy SKETCH_TOOL files work offline.":"Scegliere un tool nel menu lo seleziona soltanto: premi LOAD per caricarlo. Un nuovo LOAD ripristina i default del manifest. Mantieni insieme tools/ e l’intera cartella del device; i file INDEX_TOOL RC2 e i precedenti SKETCH_TOOL funzionano offline.","Generators draw their own canvas. Effects receive the composite of the Layers beneath them and process that result.":"I generatori disegnano sul proprio canvas. Gli effetti ricevono e modificano la composizione dei Layer sottostanti.","Each Layer remembers its section visibility. Saving a Live Set also stores the loaded tools, native values, HEX, mappings and device settings. Changing a tool resets its values: there is no separate preset memory for every tool. Keep the local tool files available when reopening a Set.":"Ogni Layer ricorda quali sezioni sono aperte. Il Live Set salva anche tool caricati, valori nativi, HEX, mappature e impostazioni. Cambiare tool ripristina i valori: non esiste una memoria preset per ciascun tool. Conserva i file locali quando riapri il Set.","Twelve numeric slots per Layer, mapped to each tool’s own manifest labels and ranges.":"Dodici slot numerici per Layer, con etichette e intervalli definiti dal manifest del tool.","Use the single reset beside a parameter for that control only. DEFAULT restores the loaded tool’s manifest defaults.":"Usa il reset accanto al parametro per ripristinare solo quel controllo. DEFAULT ripristina i valori definiti dal manifest del tool caricato.","Up to four tool-defined colors, independent opacity and per-Layer blend mode.":"Fino a quattro colori definiti dal tool, opacità indipendenti e un blend mode per Layer.","Color opacity is a native host control and does not consume P01–P12. Missing host opacity keeps the standalone tool behaviour unchanged.":"L’opacità è un controllo nativo dell’host e non occupa P01–P12. Se manca, il comportamento standalone del tool non cambia.","Velocity becomes the modulation peak. Attack rises to that peak, then release returns automatically to zero.":"La velocity determina il picco di modulazione. Attack raggiunge quel valore e Release torna automaticamente a zero.","The incoming 0–127 value becomes the target. Attack smooths upward movement; release smooths downward movement.":"Il valore CC in ingresso (0–127) diventa il target. Attack smussa la salita, Release la discesa.","Refreshes the remote catalogue and compares it with the flat local":"Aggiorna il catalogo remoto e lo confronta con la libreria locale","library. It does not download tools automatically.":": non scarica automaticamente i tool.","Depending on state, the action becomes LOAD, UPDATE or DOWNLOAD. A dropdown selection alone never changes the running Layer.":"In base allo stato, l’azione diventa LOAD, UPDATE o DOWNLOAD. La selezione dal menu non modifica mai il Layer in esecuzione.","Queues only MISSING and OUTDATED catalogue tools. CURRENT entries are left untouched; local-only fixtures remain local.":"Accoda soltanto tool MISSING e OUTDATED. I CURRENT restano invariati; i file esclusivamente locali restano locali.","A ready local Node host, a supported installed Chromium browser and compatible Canvas/WebGL support are required.":"Servono l’host Node locale pronto, un browser Chromium compatibile e il supporto Canvas/WebGL.","Mappings start unassigned. Choose the MIDI input and channel, then a slot source and NOTE/CC ID. NONE unassigns a slot. Amount sets the contribution; attack/release shape its response. Assignments are Layer-specific and saved with the Set; the functional Live controls keep their automation identities.":"Le mappature sono inizialmente vuote. Scegli ingresso e canale MIDI, sorgente dello slot e ID NOTE/CC. NONE rimuove l’assegnazione. Amount regola il contributo, Attack/Release la risposta. Ogni assegnazione è specifica del Layer e viene salvata con il Set; i controlli Live mantengono le identità di automazione.","RENDER launches the localhost compositor in an external Chromium app window. Live state reaches one compositor SSE connection, then the five tool iframes through":"RENDER avvia il compositore localhost in una finestra app Chromium esterna. Lo stato Live raggiunge una singola connessione SSE del compositore, poi i cinque iframe tramite","Actual / target FPS shows completed visual frames. The display-only dial fills up to the target and cannot be edited. FRAME CADENCE reports the observed interval between completed frames in milliseconds, not GPU execution time. PREVIEW shows the effective buffer dimensions.":"Actual / target FPS mostra i frame visual effettivamente completati. Il dial, solo indicatore, si riempie fino al target e non è modificabile. FRAME CADENCE indica in millisecondi l’intervallo osservato tra frame completati, non il tempo di esecuzione GPU. PREVIEW mostra le dimensioni reali del buffer.","AUTO follows browser / display-driven cadence; its target is estimated (~). Fixed settings request a maximum of 30 or 60 FPS across the hosted tools and compositor. Actual FPS can be lower with heavier tools.":"AUTO segue la cadenza del browser/display; il target è stimato (~). Le impostazioni fisse richiedono un massimo di 30 o 60 FPS per tool e compositore. I frame reali possono diminuire con tool più pesanti.","AUTO keeps window-dependent rendering. Fixed presets control pixel workload: 1280 × 720, 1920 × 1080, 2560 × 1440 or 3840 × 2160 in a 16:9 window. Other window shapes keep their framing and fill the window, using a buffer that fits within the preset dimensions. PREVIEW reports the actual size; Retina does not multiply a fixed preset.":"AUTO mantiene il rendering dipendente dalla finestra. I preset fissi limitano il carico pixel a 1280 × 720, 1920 × 1080, 2560 × 1440 o 3840 × 2160 in una finestra 16:9. Formati diversi mantengono l’inquadratura e riempiono la finestra usando un buffer entro le dimensioni del preset. PREVIEW indica la dimensione effettiva; Retina non moltiplica un preset fisso.","The full composition scales to the RENDER window without zooming or cropping when RES changes. Settings survive closing and reopening RENDER and are saved with the Live Set. A new unconfigured device starts from AUTO / AUTO. If a buffer is unsupported, INDEX reports the error and restores the preceding selection.":"La composizione si adatta alla finestra RENDER senza zoom o ritaglio quando RES cambia. Le impostazioni persistono dopo chiusura e riapertura di RENDER e sono salvate col Live Set. Un device nuovo parte da AUTO / AUTO. Se il buffer non è supportato, INDEX segnala l’errore e ripristina la selezione precedente.","Keep the complete folder together, load a local tool, and confirm Chromium is installed. RENDER opens an isolated app-style Chromium window; HELP uses the normal browser. Missing tool/module/font errors need the exact Console message and package version. CHECK refreshes metadata without replacing HTML; UPDATE explicitly downloads a selected tool.":"Mantieni completa la cartella, carica un tool locale e verifica che Chromium sia installato. RENDER apre una finestra Chromium isolata, HELP il browser normale. Per errori di tool, moduli o font mancanti servono il messaggio esatto della Console e la versione del pacchetto. CHECK aggiorna i metadati senza sostituire l’HTML; UPDATE scarica esplicitamente il tool selezionato.","Perform live":"Performance live","The permanent strip: project, HELP, live output and five Layers.":"La barra sempre visibile: progetto, HELP, uscita live e cinque livelli.","One dedicated live Chromium output for each Bridge instance.":"Un’uscita Chromium live dedicata per ogni istanza di Bridge.","Monitor completed live frames and choose the rendering workload.":"Controlla i frame live completati e scegli il carico di rendering.","Relate the final audio and time signals through a third independent carrier.":"Metti in relazione i segnali finali audio e tempo con un terzo segnale di modulazione indipendente.","Behaviours":"Comportamenti","MIXED":"MIXED","The library compares the files installed locally with the INDEX catalogue. These labels explain each possible result:":"La libreria confronta i file installati in locale con il catalogo INDEX. Queste etichette spiegano i possibili risultati:","Core":"Core","Mix it up":"Mescola tutto","Shape the signal":"Modella il segnale","Map it":"Mappa","Time behaviours?":"Comportamenti temporali?","Never heard of them? They can get pretty interesting.":"Mai sentiti nominare? Possono diventare piuttosto interessanti.","Send audio through the device, or feed it from another track using the SC panel.":"Fai passare audio nel device oppure invialo da un’altra traccia tramite il pannello SC.","C can combine A and B, add a little chaos, or bring mathematical constants into the mix.":"C può combinare A e B, aggiungere un po’ di caos o introdurre costanti matematiche nel mix.","Fine-tune the incoming signals and sculpt the modulation curves with plenty of control.":"Regola con precisione i segnali in ingresso e scolpisci le curve di modulazione con ampio controllo.","A, B and C each have a native 1+7 mapper. Go wild.":"A, B e C hanno ciascuno un mapper nativo 1+7. Scatenati.","A follows audio intensity from the main input or the external sidechain. Open AUDIO to shape its envelope.":"A segue l’intensità audio dell’ingresso principale o della sidechain esterna. Apri AUDIO per modellarne l’inviluppo.","Open SC to choose an external source and channel, then set Mix between the main and external analysis inputs.":"Apri SC per scegliere sorgente e canale esterni, poi regola Mix tra l’ingresso principale e quello esterno per l’analisi.","B develops with the duration of recognized contact. Open TIME for its window, growth, behaviours, hold and decay.":"B si sviluppa con la durata del contatto riconosciuto. Apri TIME per finestra, crescita, comportamenti, hold e decay.","C combines the final A and B signals, with its own scope and mapper. The Core overlays A in green, B in orange and C in yellow.":"C combina i segnali finali A e B e ha un proprio scope e mapper. La Core sovrappone A in verde, B in arancio e C in giallo.","The device includes a short on-screen message to help you understand the selected behaviour at a glance.":"Il device mostra un breve messaggio per capire a colpo d’occhio il comportamento selezionato.","SC activity":"Attività SC","Open SC, choose the source track and channel, then use Mix to blend the main input (dry) with the external source (wet) for analysis. Check A in the Core while setting the blend.":"Apri SC, scegli traccia e canale sorgente, poi usa Mix per miscelare l’ingresso principale (dry) con la sorgente esterna (wet) per l’analisi. Controlla A nella Core mentre regoli la miscela.","The SC button blinks even when the panel is closed when the device is on, an external route is valid and Mix is above zero. It indicates active routing, including when the source is silent. SC opens to the left of the Core; AUDIO, TIME and MIXED open independently to the right.":"Il pulsante SC lampeggia anche a pannello chiuso quando il device è acceso, il routing esterno è valido e Mix è maggiore di zero. Indica il routing attivo anche se la sorgente è silenziosa. SC si apre a sinistra della Core; AUDIO, TIME e MIXED si aprono indipendentemente a destra.","Open L1–L5, choose a tool and check its library status. Press LOAD, UPDATE or DOWNLOAD to use it; selecting the name alone does not change the running Layer.":"Apri L1–L5, scegli un tool e controllane lo stato nella libreria. Premi LOAD, UPDATE o DOWNLOAD per usarlo: selezionare il nome non cambia il Layer in esecuzione.","Open the online HELP in your normal browser. The current device button opens the BeerBelgio homepage while the product guide is being prepared.":"Apri la HELP online nel browser abituale. Il pulsante attuale apre la homepage BeerBelgio mentre la guida specifica è in preparazione.","RENDER uses a private browser session for each instance. It is designed to close its rendering processes when you close the output, toggle RENDER, switch Live Sets or quit Live. If the output remains open, see Troubleshooting.":"RENDER usa una sessione browser privata per ogni istanza. È progettato per chiudere i processi di rendering quando chiudi l’output, disattivi RENDER, cambi Live Set o esci da Live. Se l’output resta aperto, consulta Risoluzione problemi.","Contact begins with duration: TIME GATE sets how long the signal must stay above the AUDIO Threshold before B starts growing. Gate spans 0–2000 ms in 5 ms steps; 0 starts immediately. AUDIO Threshold sets the separate amplitude condition after Gain/Rise/Fall and before Audio Amount (default 5%; effective range 0.1–95%).":"Il contatto comincia dalla durata: TIME GATE stabilisce per quanto tempo il segnale deve restare sopra AUDIO Threshold prima che B inizi a crescere. Gate varia da 0 a 2000 ms a passi di 5 ms; 0 avvia subito. AUDIO Threshold definisce la condizione separata di ampiezza dopo Gain/Rise/Fall e prima di Audio Amount (default 5%; intervallo effettivo 0.1–95%).","C reads the final A and B outputs without feeding back into them. It has an independent trace and mapper, updated on the existing nominal 5 ms tick.":"C legge le uscite finali A e B senza retroazione. Ha una traccia e un mapper indipendenti, aggiornati sul tick nominale esistente di 5 ms.","CONSEQUENCE OF TIME is in testing and is not publicly distributed. No installation package or download is offered here.":"CONSEQUENCE OF TIME è in fase di test e non è distribuito pubblicamente. Qui non sono disponibili pacchetti di installazione o download.","87 functional Live controls keep their identities, plus one hidden performance gauge. Each of the five Layers exposes up to 12 numeric slots, with independent color opacity and visibility controls.":"Gli 87 controlli funzionali Live conservano le proprie identità, con un indicatore di prestazioni nascosto aggiuntivo. Ognuno dei cinque Layer espone fino a 12 slot numerici, con controlli indipendenti di opacità colore e visibilità.","The Live parameter remains the automation and external modulation target. Internal Note/CC temporarily owns the final value of an assigned slot; choose NONE to return it to native editing.":"Il parametro Live resta la destinazione di automazione e modulazione esterna. Note/CC interno controlla temporaneamente il valore finale di uno slot assegnato; scegli NONE per tornare alla modifica nativa.","Choose NONE to return an internally mapped slot to native editing. Check its final value and destination response after changing assignment.":"Scegli NONE per restituire uno slot mappato internamente alla modifica nativa. Controlla il valore finale e la risposta della destinazione dopo aver cambiato assegnazione.","Up to four manifest-defined colors per Layer. Edit them with the native picker or #RRGGBB text; unused slots display UNUSED.":"Fino a quattro colori definiti dal manifest per Layer. Modificali con il selettore nativo o il testo #RRGGBB; gli slot inutilizzati mostrano UNUSED.","Open one Layer editor; click its control again to close it.":"Apri un editor Layer; premi di nuovo il suo controllo per chiuderlo.","Include or exclude each Layer independently from editor visibility.":"Includi o escludi ogni Layer indipendentemente dalla visibilità del suo editor.","Open the INDEX HTML project website.":"Apri il sito del progetto INDEX HTML.","Toggle one dedicated Chromium output owned by this Bridge instance.":"Attiva o disattiva l’output Chromium dedicato a questa istanza Bridge.","Installation metadata or resolved local file is absent.":"Mancano i metadati di installazione o il file locale risolto.","Installed entry absent from the remote catalogue, with an existing local file.":"Voce installata assente dal catalogo remoto, con file locale presente.","Local file exists and installation version differs from catalogue version.":"Il file locale esiste e la versione installata differisce dal catalogo.","Local file exists and installation version equals catalogue version.":"Il file locale esiste e la versione installata coincide con il catalogo.","Analyze the audio passing through the track that contains Consequence of Time.":"Analizza l’audio che passa nella traccia contenente CONSEQUENCE OF TIME."},"de":{"Quick start":"Schnellstart","Troubleshooting":"Fehlerbehebung","Under the hood":"Unter der Haube","Layers":"Ebenen","Params":"Parameter","Parameters":"Parameter","Color":"Farbe","Library":"Bibliothek","Performance":"Leistung","Time":"Zeit","Mapping":"Zuordnung","REPORT AN ISSUE":"PROBLEM MELDEN","Report an issue or get in touch.":"Ein Problem melden oder Kontakt aufnehmen.","Having trouble with INDEX HTML BRIDGE? Get in touch.":"Probleme mit INDEX HTML BRIDGE? Melde dich.","Having trouble with CONSEQUENCE OF TIME? Get in touch.":"Probleme mit CONSEQUENCE OF TIME? Melde dich.","Send some audio":"Audiosignal zuführen","Shape the audio-responsive signal A.":"Das auf Audio reagierende Signal A formen.","Audio source":"Audioquelle","Use the main track input or select an external sidechain. Check routing when nothing moves.":"Haupteingang der Spur oder externe Sidechain verwenden. Falls sich nichts bewegt, Routing prüfen.","Adjust incoming level before the signal is analyzed.":"Den Eingangspegel vor der Analyse anpassen.","Set how quickly signal A reacts to increasing and decreasing audio intensity. These controls do not modify B Attack, Hold or Decay.":"Bestimmt, wie schnell A auf steigende oder fallende Audiointensität reagiert. B Attack, Hold und Decay bleiben unverändert.","Adjust the amount applied to normalized A. It is not the contact threshold used by the time engine.":"Bestimmt die Stärke des normierten Signals A. Dies ist nicht die Kontaktschwelle der Zeitlogik.","Build a time-driven signal B from recognized contact.":"Ein zeitgesteuertes Signal B aus erkanntem Kontakt erzeugen.","Contact threshold":"Kontaktschwelle","Choose BEATS (musical tempo) or TIME (elapsed time) as the accumulation window; the two modes retain separate values.":"BEATS (musikalisches Tempo) oder TIME (verstrichene Zeit) als Akkumulationsfenster wählen; beide Modi speichern getrennte Werte.","Set initial signal level and range of movement.":"Startpegel und Bewegungsbereich des Signals festlegen.","Attack smooths growth, Hold keeps the value after contact is lost, Decay returns B toward zero.":"Attack glättet den Anstieg, Hold hält den Wert nach Kontaktverlust und Decay führt B gegen null zurück.","Pure time evolution. Time Amount has no effect in CLEAN.":"Reiner Zeitverlauf. Time Amount hat in CLEAN keinen Effekt.","Changes movement range in response to intensity.":"Verändert den Bewegungsbereich je nach Intensität.","Changes accumulation speed in response to intensity.":"Verändert die Akkumulationsgeschwindigkeit je nach Intensität.","Adds signal-dependent irregular fluctuations.":"Fügt signalabhängige unregelmäßige Schwankungen hinzu.","May produce a descending positive curve, not negative output; transitions can be abrupt.":"Kann eine abfallende positive Kurve erzeugen, aber keinen negativen Ausgang; Übergänge können abrupt sein.","Can pause time progress when intensity meets its condition.":"Kann den Zeitfortschritt anhalten, wenn die Intensitätsbedingung erfüllt ist.","Quantizes the time signal into discrete steps.":"Quantisiert das Zeitsignal in einzelne Stufen.","Combines speed changes and irregular fluctuations. Time Amount adjusts each active behavior, not the basic B Depth.":"Kombiniert Geschwindigkeitsänderungen und unregelmäßige Schwankungen. Time Amount steuert den jeweiligen Effekt, nicht die grundlegende B Depth.","Mod works as relative modulation around a parameter base value. Remote takes exclusive control of its destination. These are native Ableton behaviors.":"Mod moduliert relativ zum Basiswert eines Parameters. Remote übernimmt die alleinige Kontrolle des Ziels. Beides ist natives Ableton-Verhalten.","Save & Reload":"Speichern & neu laden","After mapping, verify actual modulation after saving and reopening the Live Set — not only that the destination name persists.":"Nach dem Zuordnen den Live Set speichern und erneut öffnen; prüfen, ob die Modulation wirklich arbeitet, nicht nur der Zielname erhalten bleibt.","Distribution note":"Hinweis zur Distribution","Choose a separate source for audio analysis.":"Eine separate Quelle für die Audioanalyse wählen.","Main audio":"Hauptaudio","External sidechain":"Externe Sidechain","Common checks for signal, timing and mapping.":"Häufige Prüfungen für Signal, Timing und Zuordnung.","No signal movement":"Keine Signalbewegung","Confirm that audio is present, inspect source and routing, increase Gain as appropriate, and check the contact threshold and B Depth.":"Audioeingang, Quelle und Routing prüfen, Gain bei Bedarf erhöhen sowie Kontaktschwelle und B Depth prüfen.","A moves but B does not":"A bewegt sich, B nicht","Check the threshold and Tolerance, the Window, Growth, B Start/Depth and whether sufficient contact time has accumulated.":"Schwelle, Tolerance, Window, Growth und B Start/Depth prüfen sowie die akkumulierte Kontaktdauer kontrollieren.","Mapping looks static":"Zuordnung scheint statisch","In Mod mode, the base knob may stay at its set value while modulation operates. Check the destination response, not only the knob position.":"Im Mod-Modus kann der Basisregler unverändert bleiben, obwohl die Modulation arbeitet. Prüfe das Zielverhalten statt nur die Reglerposition.","A: amplitude response":"A: Amplitudenreaktion","The envelope follower translates the level of the input signal into a continuous normalized modulation output.":"Der Envelope Follower wandelt den Eingangspegel in ein kontinuierliches, normiertes Modulationssignal um.","B: duration response":"B: Dauerreaktion","Contact recognition drives a separate time engine. Window, Growth, Accel, Hold, Decay and Behavior change the shape of B.":"Die Kontakterkennung steuert eine eigene Zeitlogik. Window, Growth, Accel, Hold, Decay und Behavior formen B.","Audio transparency":"Audiotransparenz","Shape it":"Gestalten","Open PARAMETERS, COLORS & BLEND and MIDI MAPPING in any combination.":"PARAMETERS, COLORS & BLEND und MIDI MAPPING beliebig kombinieren.","Render live":"Live rendern","RENDER opens the external Chromium compositor. Your five Layers are combined there.":"RENDER öffnet den externen Chromium-Compositor, der die fünf Ebenen zusammensetzt.","Five independent visual slots, composed from L1 upward. Effects process only what sits below them.":"Fünf unabhängige visuelle Ebenen ab L1; Effekte bearbeiten nur die darunterliegenden Ebenen.","One editor, five layers":"Ein Editor, fünf Ebenen","Tool loading":"Tool laden","Generator vs effect":"Generator oder Effekt","Remembered per layer":"Pro Ebene gespeichert","Native Live parameters":"Native Live-Parameter","Reset & defaults":"Zurücksetzen & Standardwerte","Effective values":"Effektive Werte","Automation stays yours":"Automation bleibt erhalten","Colors & Blend":"Farben & Blend","Effect Layers do not use generator blend in the same way: their shader processes the lower composite directly.":"Effekte nutzen den Generator-Blend nicht auf dieselbe Weise: Ihr Shader verarbeitet direkt die unteren Ebenen.","MIDI Mapping":"MIDI-Zuordnung","Map NOTE or CC directly onto P01–P12 with amount and envelope/smoothing controls.":"NOTE oder CC direkt auf P01–P12 zuordnen, mit Stärke und Hüllkurven-/Glättungsreglern.","Selected tool":"Ausgewähltes Tool","Requirements":"Anforderungen","Live output":"Live-Ausgabe","Live Render Performance":"Leistung beim Live-Rendering","Automatic panel":"Automatisches Panel","Read the monitor":"Monitor lesen","Same view, different quality":"Gleiche Ansicht, andere Qualität","The useful failure boundaries, current limitations and what not to expect from this build.":"Wichtige Fehlergrenzen, aktuelle Einschränkungen und was diese Version nicht leistet.","Browser or missing resources":"Browser oder fehlende Ressourcen","Only if you care: how Max, Node and Chromium divide the work.":"Für Interessierte: So teilen Max, Node und Chromium die Arbeit auf.","No Jitter renderer":"Kein Jitter-Renderer","INDEX HTML stays browser-native. The fundamental split is simple: Max decides what happens; the browser decides how to draw it.":"INDEX HTML bleibt browsernativ: Max entscheidet, was geschieht; der Browser entscheidet, wie es dargestellt wird.","Open one Layer editor at a time. Layer visibility is independent from whether its editor is open.":"Immer nur einen Layer-Editor öffnen. Die Sichtbarkeit einer Ebene hängt nicht vom geöffneten Editor ab.","Choosing a tool in the dropdown only selects it. Press LOAD to use the selection. A new LOAD restores manifest defaults. Keep tools/ and the complete device folder together; local INDEX_TOOL RC2 and legacy SKETCH_TOOL files work offline.":"Die Auswahl im Dropdown lädt das Tool nicht. Mit LOAD wird es gestartet; erneutes LOAD stellt Manifest-Defaults wieder her. tools/ und Device-Ordner zusammenhalten; INDEX_TOOL RC2 und ältere SKETCH_TOOL-Dateien funktionieren offline.","Generators draw their own canvas. Effects receive the composite of the Layers beneath them and process that result.":"Generatoren zeichnen auf ihre eigene Canvas. Effekte verarbeiten die Kombination der darunterliegenden Ebenen.","Each Layer remembers its section visibility. Saving a Live Set also stores the loaded tools, native values, HEX, mappings and device settings. Changing a tool resets its values: there is no separate preset memory for every tool. Keep the local tool files available when reopening a Set.":"Jede Ebene merkt sich geöffnete Bereiche. Live Sets speichern geladene Tools, native Werte, HEX-Farben, Mappings und Einstellungen. Beim Toolwechsel werden Werte zurückgesetzt; es gibt keinen eigenen Preset-Speicher je Tool. Lokale Tool-Dateien beim erneuten Öffnen bereithalten.","Twelve numeric slots per Layer, mapped to each tool’s own manifest labels and ranges.":"Zwölf numerische Slots pro Ebene, deren Namen und Bereiche das jeweilige Tool-Manifest vorgibt.","Use the single reset beside a parameter for that control only. DEFAULT restores the loaded tool’s manifest defaults.":"Der Reset neben einem Parameter betrifft nur diesen Regler. DEFAULT stellt die Standardwerte des geladenen Tools wieder her.","Up to four tool-defined colors, independent opacity and per-Layer blend mode.":"Bis zu vier tooldefinierte Farben mit eigener Deckkraft und einem Blend-Modus pro Ebene.","Color opacity is a native host control and does not consume P01–P12. Missing host opacity keeps the standalone tool behaviour unchanged.":"Deckkraft ist eine native Host-Steuerung und belegt keinen Slot P01–P12. Ohne Host-Deckkraft bleibt das Standalone-Verhalten gleich.","Velocity becomes the modulation peak. Attack rises to that peak, then release returns automatically to zero.":"Velocity bestimmt die Modulationsspitze. Attack steigt dorthin, Release fällt automatisch auf null zurück.","The incoming 0–127 value becomes the target. Attack smooths upward movement; release smooths downward movement.":"Der eingehende CC-Wert von 0 bis 127 wird zum Ziel. Attack glättet Aufwärtsbewegungen, Release Abwärtsbewegungen.","Refreshes the remote catalogue and compares it with the flat local":"Aktualisiert den Remote-Katalog und vergleicht ihn mit der lokalen","library. It does not download tools automatically.":"Bibliothek. Tools werden nicht automatisch heruntergeladen.","Depending on state, the action becomes LOAD, UPDATE or DOWNLOAD. A dropdown selection alone never changes the running Layer.":"Je nach Zustand heißt die Aktion LOAD, UPDATE oder DOWNLOAD. Eine Dropdown-Auswahl allein ändert die laufende Ebene nie.","Queues only MISSING and OUTDATED catalogue tools. CURRENT entries are left untouched; local-only fixtures remain local.":"Nimmt nur MISSING- und OUTDATED-Tools in die Warteschlange. CURRENT bleibt unberührt; rein lokale Dateien bleiben lokal.","A ready local Node host, a supported installed Chromium browser and compatible Canvas/WebGL support are required.":"Ein laufender lokaler Node-Host, ein unterstützter Chromium-Browser sowie Canvas/WebGL-Unterstützung sind erforderlich.","Mappings start unassigned. Choose the MIDI input and channel, then a slot source and NOTE/CC ID. NONE unassigns a slot. Amount sets the contribution; attack/release shape its response. Assignments are Layer-specific and saved with the Set; the functional Live controls keep their automation identities.":"Mappings beginnen ohne Zuweisung. MIDI-Eingang und Kanal sowie Slot-Quelle und NOTE-/CC-ID wählen. NONE entfernt die Zuweisung. Amount bestimmt den Beitrag, Attack/Release formen die Reaktion. Zuweisungen gelten pro Ebene und werden mit dem Set gespeichert; Live-Steuerungen behalten ihre Automationsidentitäten.","RENDER launches the localhost compositor in an external Chromium app window. Live state reaches one compositor SSE connection, then the five tool iframes through":"RENDER startet den localhost-Compositor in einem externen Chromium-App-Fenster. Der Live-Zustand gelangt über eine SSE-Verbindung zum Compositor und dann zu den fünf Tool-Iframes über","Actual / target FPS shows completed visual frames. The display-only dial fills up to the target and cannot be edited. FRAME CADENCE reports the observed interval between completed frames in milliseconds, not GPU execution time. PREVIEW shows the effective buffer dimensions.":"Actual / target FPS zeigt fertig gerenderte Frames. Der rein anzeigende Regler füllt sich bis zum Zielwert und ist nicht editierbar. FRAME CADENCE misst den Abstand zwischen fertigen Frames in Millisekunden, nicht die GPU-Rechenzeit. PREVIEW zeigt die tatsächlichen Buffermaße.","AUTO follows browser / display-driven cadence; its target is estimated (~). Fixed settings request a maximum of 30 or 60 FPS across the hosted tools and compositor. Actual FPS can be lower with heavier tools.":"AUTO folgt dem Takt von Browser/Display, der Zielwert ist geschätzt (~). Feste Einstellungen begrenzen Tools und Compositor auf höchstens 30 oder 60 FPS. Mit anspruchsvollen Tools können die tatsächlichen FPS sinken.","AUTO keeps window-dependent rendering. Fixed presets control pixel workload: 1280 × 720, 1920 × 1080, 2560 × 1440 or 3840 × 2160 in a 16:9 window. Other window shapes keep their framing and fill the window, using a buffer that fits within the preset dimensions. PREVIEW reports the actual size; Retina does not multiply a fixed preset.":"AUTO passt das Rendering der Fenstergröße an. Feste Presets begrenzen die Pixelarbeit auf 1280 × 720, 1920 × 1080, 2560 × 1440 oder 3840 × 2160 bei 16:9. Andere Fensterformate behalten den Bildausschnitt und füllen das Fenster mit einem Buffer innerhalb der Presetgrenzen. PREVIEW zeigt die tatsächliche Größe; Retina vervielfacht feste Presets nicht.","The full composition scales to the RENDER window without zooming or cropping when RES changes. Settings survive closing and reopening RENDER and are saved with the Live Set. A new unconfigured device starts from AUTO / AUTO. If a buffer is unsupported, INDEX reports the error and restores the preceding selection.":"Die gesamte Komposition wird bei RES-Änderungen ohne Zoom oder Beschnitt ans RENDER-Fenster skaliert. Einstellungen bleiben beim Schließen erhalten und werden im Live Set gespeichert. Neue Devices beginnen mit AUTO / AUTO. Ist ein Buffer nicht unterstützt, meldet INDEX einen Fehler und stellt die vorherige Auswahl wieder her.","Keep the complete folder together, load a local tool, and confirm Chromium is installed. RENDER opens an isolated app-style Chromium window; HELP uses the normal browser. Missing tool/module/font errors need the exact Console message and package version. CHECK refreshes metadata without replacing HTML; UPDATE explicitly downloads a selected tool.":"Vollständigen Ordner zusammenhalten, lokales Tool laden und Chromium-Installation prüfen. RENDER öffnet ein isoliertes Chromium-App-Fenster, HELP den normalen Browser. Bei fehlenden Tools/Modulen/Schriften die genaue Console-Meldung und Paketversion notieren. CHECK aktualisiert Metadaten ohne HTML-Ersatz; UPDATE lädt ausgewählte Tools ausdrücklich herunter.","The library compares the files installed locally with the INDEX catalogue. These labels explain each possible result:":"Die Bibliothek vergleicht lokal installierte Dateien mit dem INDEX-Katalog. Diese Bezeichnungen erläutern die möglichen Ergebnisse:","Core":"Core","Mix it up":"Mische es auf","Shape the signal":"Forme das Signal","Map it":"Zuweisen","Time behaviours?":"Zeitverhalten?","Never heard of them? They can get pretty interesting.":"Noch nie davon gehört? Sie können ziemlich interessant werden.","Send audio through the device, or feed it from another track using the SC panel.":"Leite Audio durch das Gerät oder führe es über das SC-Panel von einer anderen Spur zu.","C can combine A and B, add a little chaos, or bring mathematical constants into the mix.":"C kann A und B kombinieren, etwas Chaos hinzufügen oder mathematische Konstanten ins Spiel bringen.","Fine-tune the incoming signals and sculpt the modulation curves with plenty of control.":"Stimme die Eingangssignale fein ab und forme die Modulationskurven mit vielen Eingriffsmöglichkeiten.","A, B and C each have a native 1+7 mapper. Go wild.":"A, B und C haben jeweils einen nativen 1+7-Mapper. Lass deiner Kreativität freien Lauf.","A follows audio intensity from the main input or the external sidechain. Open AUDIO to shape its envelope.":"A folgt der Audiointensität des Haupteingangs oder der externen Sidechain. Öffne AUDIO, um die Hüllkurve zu formen.","Open SC to choose an external source and channel, then set Mix between the main and external analysis inputs.":"Öffne SC, wähle eine externe Quelle und einen Kanal und stelle Mix zwischen Haupt- und externem Analyseeingang ein.","B develops with the duration of recognized contact. Open TIME for its window, growth, behaviours, hold and decay.":"B entwickelt sich mit der Dauer des erkannten Kontakts. Öffne TIME für Zeitfenster, Wachstum, Verhalten, Hold und Decay.","C combines the final A and B signals, with its own scope and mapper. The Core overlays A in green, B in orange and C in yellow.":"C kombiniert die endgültigen Signale A und B mit eigenem Scope und Mapper. Die Core zeigt A grün, B orange und C gelb übereinander.","The device includes a short on-screen message to help you understand the selected behaviour at a glance.":"Eine kurze Bildschirmmeldung hilft dir, das gewählte Verhalten auf einen Blick zu verstehen.","SC activity":"SC-Aktivität","Open SC, choose the source track and channel, then use Mix to blend the main input (dry) with the external source (wet) for analysis. Check A in the Core while setting the blend.":"Öffne SC, wähle Quellspur und Kanal und mische mit Mix den Haupteingang (dry) mit der externen Quelle (wet) zur Analyse. Beobachte dabei A in der Core.","The SC button blinks even when the panel is closed when the device is on, an external route is valid and Mix is above zero. It indicates active routing, including when the source is silent. SC opens to the left of the Core; AUDIO, TIME and MIXED open independently to the right.":"Die SC-Taste blinkt auch bei geschlossenem Panel, wenn das Gerät an, eine externe Route gültig und Mix größer null ist. Sie zeigt aktives Routing auch bei stiller Quelle an. SC öffnet links der Core; AUDIO, TIME und MIXED öffnen unabhängig rechts.","Open L1–L5, choose a tool and check its library status. Press LOAD, UPDATE or DOWNLOAD to use it; selecting the name alone does not change the running Layer.":"Öffne L1–L5, wähle ein Tool und prüfe seinen Bibliotheksstatus. Nutze LOAD, UPDATE oder DOWNLOAD; die Namensauswahl allein ändert den laufenden Layer nicht.","Open the online HELP in your normal browser. The current device button opens the BeerBelgio homepage while the product guide is being prepared.":"Öffne die Online-HELP im normalen Browser. Die aktuelle Taste öffnet die BeerBelgio-Homepage, während die Produktanleitung vorbereitet wird.","RENDER uses a private browser session for each instance. It is designed to close its rendering processes when you close the output, toggle RENDER, switch Live Sets or quit Live. If the output remains open, see Troubleshooting.":"RENDER verwendet eine private Browsersitzung je Instanz. Die Renderprozesse sollen beim Schließen der Ausgabe, Umschalten von RENDER, Wechseln des Live Sets oder Beenden von Live schließen. Bleibt die Ausgabe offen, siehe Fehlerbehebung.","Contact begins with duration: TIME GATE sets how long the signal must stay above the AUDIO Threshold before B starts growing. Gate spans 0–2000 ms in 5 ms steps; 0 starts immediately. AUDIO Threshold sets the separate amplitude condition after Gain/Rise/Fall and before Audio Amount (default 5%; effective range 0.1–95%).":"Kontakt beginnt mit der Dauer: TIME GATE legt fest, wie lange das Signal über AUDIO Threshold bleiben muss, bevor B wächst. Gate reicht von 0 bis 2000 ms in 5-ms-Schritten; 0 startet sofort. AUDIO Threshold bestimmt getrennt davon die Amplitudenbedingung nach Gain/Rise/Fall und vor Audio Amount (Standard 5 %; effektiver Bereich 0,1–95 %).","C reads the final A and B outputs without feeding back into them. It has an independent trace and mapper, updated on the existing nominal 5 ms tick.":"C liest die endgültigen A- und B-Ausgänge ohne Rückkopplung. Es hat eine eigene Spur und einen Mapper, aktualisiert im bestehenden nominalen 5-ms-Takt.","CONSEQUENCE OF TIME is in testing and is not publicly distributed. No installation package or download is offered here.":"CONSEQUENCE OF TIME wird getestet und ist nicht öffentlich verfügbar. Hier wird kein Installationspaket oder Download angeboten.","87 functional Live controls keep their identities, plus one hidden performance gauge. Each of the five Layers exposes up to 12 numeric slots, with independent color opacity and visibility controls.":"87 funktionale Live-Regler behalten ihre Identität, ergänzt um eine versteckte Leistungsanzeige. Jeder der fünf Layer bietet bis zu 12 numerische Slots sowie unabhängige Farbdeckkraft- und Sichtbarkeitsregler.","The Live parameter remains the automation and external modulation target. Internal Note/CC temporarily owns the final value of an assigned slot; choose NONE to return it to native editing.":"Der Live-Parameter bleibt Ziel von Automation und externer Modulation. Internes Note/CC steuert vorübergehend den Endwert eines zugewiesenen Slots; NONE gibt die native Bearbeitung zurück.","Choose NONE to return an internally mapped slot to native editing. Check its final value and destination response after changing assignment.":"Wähle NONE, um einen intern zugewiesenen Slot wieder nativ zu bearbeiten. Prüfe nach der Änderung den Endwert und die Reaktion des Ziels.","Up to four manifest-defined colors per Layer. Edit them with the native picker or #RRGGBB text; unused slots display UNUSED.":"Bis zu vier manifestdefinierte Farben je Layer. Bearbeite sie mit dem nativen Farbwähler oder #RRGGBB-Text; ungenutzte Slots zeigen UNUSED.","Open one Layer editor; click its control again to close it.":"Öffne einen Layer-Editor; ein erneuter Klick auf seinen Regler schließt ihn.","Include or exclude each Layer independently from editor visibility.":"Schalte jeden Layer unabhängig von der Sichtbarkeit seines Editors ein oder aus.","Open the INDEX HTML project website.":"Öffne die Website des INDEX HTML-Projekts.","Toggle one dedicated Chromium output owned by this Bridge instance.":"Schalte eine dedizierte Chromium-Ausgabe dieser Bridge-Instanz um.","Installation metadata or resolved local file is absent.":"Installationsmetadaten oder die aufgelöste lokale Datei fehlen.","Installed entry absent from the remote catalogue, with an existing local file.":"Installierter Eintrag fehlt im Remote-Katalog, seine lokale Datei ist vorhanden.","Local file exists and installation version differs from catalogue version.":"Lokale Datei vorhanden; installierte Version weicht vom Katalog ab.","Local file exists and installation version equals catalogue version.":"Lokale Datei vorhanden; installierte Version entspricht dem Katalog."},"es":{"Support":"Soporte","Quick start":"Inicio rápido","Troubleshooting":"Solución de problemas","Under the hood":"Cómo funciona","Layers":"Capas","Params":"Parámetros","Parameters":"Parámetros","Library":"Biblioteca","Performance":"Rendimiento","Time":"Tiempo","Mapping":"Asignación","REPORT AN ISSUE":"INFORMAR DE UN PROBLEMA","Report an issue or get in touch.":"Informa de un problema o ponte en contacto.","Having trouble with INDEX HTML BRIDGE? Get in touch.":"¿Problemas con INDEX HTML BRIDGE? Escríbeme.","Having trouble with CONSEQUENCE OF TIME? Get in touch.":"¿Problemas con CONSEQUENCE OF TIME? Escríbeme.","Send some audio":"Envía una señal de audio","Shape the audio-responsive signal A.":"Moldea la señal A sensible al audio.","Audio source":"Fuente de audio","Use the main track input or select an external sidechain. Check routing when nothing moves.":"Usa la entrada de la pista o una sidechain externa. Si no se mueve nada, revisa el enrutamiento.","Adjust incoming level before the signal is analyzed.":"Ajusta el nivel de entrada antes del análisis.","Set how quickly signal A reacts to increasing and decreasing audio intensity. These controls do not modify B Attack, Hold or Decay.":"Ajusta la rapidez con la que A responde a aumentos y descensos de intensidad. No modifica Attack, Hold ni Decay de B.","Adjust the amount applied to normalized A. It is not the contact threshold used by the time engine.":"Ajusta la cantidad aplicada a A normalizada. No es el umbral de contacto del motor temporal.","Build a time-driven signal B from recognized contact.":"Construye una señal temporal B a partir del contacto detectado.","Contact threshold":"Umbral de contacto","Choose BEATS (musical tempo) or TIME (elapsed time) as the accumulation window; the two modes retain separate values.":"Elige BEATS (tempo musical) o TIME (tiempo transcurrido) como ventana de acumulación; cada modo conserva sus propios valores.","Set initial signal level and range of movement.":"Define el nivel inicial y el rango de movimiento de la señal.","Attack smooths growth, Hold keeps the value after contact is lost, Decay returns B toward zero.":"Attack suaviza el crecimiento; Hold mantiene el valor tras perder contacto; Decay devuelve B hacia cero.","Pure time evolution. Time Amount has no effect in CLEAN.":"Evolución temporal pura. Time Amount no tiene efecto en CLEAN.","Changes movement range in response to intensity.":"Modifica el rango de movimiento según la intensidad.","Changes accumulation speed in response to intensity.":"Modifica la velocidad de acumulación según la intensidad.","Adds signal-dependent irregular fluctuations.":"Añade fluctuaciones irregulares dependientes de la señal.","May produce a descending positive curve, not negative output; transitions can be abrupt.":"Puede generar una curva positiva descendente, no una salida negativa; las transiciones pueden ser bruscas.","Can pause time progress when intensity meets its condition.":"Puede detener el avance del tiempo cuando se cumple la condición de intensidad.","Quantizes the time signal into discrete steps.":"Cuantiza la señal temporal en pasos discretos.","Combines speed changes and irregular fluctuations. Time Amount adjusts each active behavior, not the basic B Depth.":"Combina cambios de velocidad y fluctuaciones irregulares. Time Amount ajusta el efecto activo, no el B Depth básico.","Mod works as relative modulation around a parameter base value. Remote takes exclusive control of its destination. These are native Ableton behaviors.":"Mod modula de forma relativa al valor base del parámetro. Remote toma el control exclusivo del destino. Son comportamientos nativos de Ableton.","Save & Reload":"Guardar y reabrir","After mapping, verify actual modulation after saving and reopening the Live Set — not only that the destination name persists.":"Después de asignar, guarda y reabre el Live Set para comprobar la modulación real, no solo que persista el nombre del destino.","Distribution note":"Nota sobre distribución","Choose a separate source for audio analysis.":"Selecciona una fuente aparte para el análisis de audio.","Main audio":"Audio principal","External sidechain":"Sidechain externa","Common checks for signal, timing and mapping.":"Comprobaciones habituales de señal, tiempo y asignación.","No signal movement":"La señal no se mueve","Confirm that audio is present, inspect source and routing, increase Gain as appropriate, and check the contact threshold and B Depth.":"Comprueba que llega audio, revisa fuente y enrutamiento, aumenta Gain si procede y verifica el umbral y B Depth.","A moves but B does not":"A se mueve pero B no","Check the threshold and Tolerance, the Window, Growth, B Start/Depth and whether sufficient contact time has accumulated.":"Revisa umbral, Tolerance, Window, Growth, B Start/Depth y que se haya acumulado suficiente tiempo de contacto.","Mapping looks static":"La asignación parece estática","In Mod mode, the base knob may stay at its set value while modulation operates. Check the destination response, not only the knob position.":"En modo Mod, el mando base puede permanecer fijo mientras actúa la modulación. Comprueba la respuesta del destino, no solo el mando.","A: amplitude response":"A: respuesta de amplitud","The envelope follower translates the level of the input signal into a continuous normalized modulation output.":"El seguidor de envolvente convierte el nivel de entrada en una modulación continua normalizada.","B: duration response":"B: respuesta de duración","Contact recognition drives a separate time engine. Window, Growth, Accel, Hold, Decay and Behavior change the shape of B.":"La detección de contacto controla un motor temporal aparte. Window, Growth, Accel, Hold, Decay y Behavior modifican B.","Audio transparency":"Transparencia de audio","Shape it":"Dale forma","Open PARAMETERS, COLORS & BLEND and MIDI MAPPING in any combination.":"Abre PARAMETERS, COLORS & BLEND y MIDI MAPPING en cualquier combinación.","Render live":"Renderiza en directo","RENDER opens the external Chromium compositor. Your five Layers are combined there.":"RENDER abre el compositor externo Chromium y combina las cinco capas.","Five independent visual slots, composed from L1 upward. Effects process only what sits below them.":"Cinco capas visuales independientes, compuestas desde L1. Los efectos procesan lo que está por debajo.","One editor, five layers":"Un editor, cinco capas","Tool loading":"Carga de herramienta","Generator vs effect":"Generador o efecto","Remembered per layer":"Memoria por capa","Native Live parameters":"Parámetros Live nativos","Reset & defaults":"Restablecer y valores iniciales","Effective values":"Valores efectivos","Automation stays yours":"La automatización sigue intacta","Colors & Blend":"Colores y mezcla","Effect Layers do not use generator blend in the same way: their shader processes the lower composite directly.":"Las capas de efectos no usan la mezcla como los generadores: su shader procesa directamente la composición inferior.","MIDI Mapping":"Mapeo MIDI","Map NOTE or CC directly onto P01–P12 with amount and envelope/smoothing controls.":"Asigna NOTE o CC directamente a P01–P12, con cantidad y controles de envolvente/suavizado.","Status":"Estado","Selected tool":"Herramienta seleccionada","Requirements":"Requisitos","Live output":"Salida en directo","Live Render Performance":"Rendimiento del render en directo","Automatic panel":"Panel automático","Read the monitor":"Leer el monitor","Same view, different quality":"Misma vista, distinta calidad","The useful failure boundaries, current limitations and what not to expect from this build.":"Límites de fallo útiles, limitaciones actuales y qué no esperar de esta versión.","Browser or missing resources":"Navegador o recursos ausentes","Only if you care: how Max, Node and Chromium divide the work.":"Si quieres profundizar: cómo se reparten el trabajo Max, Node y Chromium.","No Jitter renderer":"Sin renderizador Jitter","INDEX HTML stays browser-native. The fundamental split is simple: Max decides what happens; the browser decides how to draw it.":"INDEX HTML sigue siendo nativo del navegador: Max decide qué ocurre y el navegador cómo dibujarlo.","Open one Layer editor at a time. Layer visibility is independent from whether its editor is open.":"Abre un editor de capa a la vez. Su visibilidad es independiente de que el editor esté abierto.","Choosing a tool in the dropdown only selects it. Press LOAD to use the selection. A new LOAD restores manifest defaults. Keep tools/ and the complete device folder together; local INDEX_TOOL RC2 and legacy SKETCH_TOOL files work offline.":"Elegir una herramienta en el menú solo la selecciona: pulsa LOAD para usarla. Un nuevo LOAD restaura los valores del manifest. Mantén tools/ junto a la carpeta completa del dispositivo; INDEX_TOOL RC2 y SKETCH_TOOL antiguos funcionan offline.","Generators draw their own canvas. Effects receive the composite of the Layers beneath them and process that result.":"Los generadores dibujan en su propio canvas. Los efectos procesan la composición de las capas inferiores.","Each Layer remembers its section visibility. Saving a Live Set also stores the loaded tools, native values, HEX, mappings and device settings. Changing a tool resets its values: there is no separate preset memory for every tool. Keep the local tool files available when reopening a Set.":"Cada capa recuerda sus secciones abiertas. El Live Set guarda herramientas, valores nativos, HEX, asignaciones y ajustes. Cambiar de herramienta restaura sus valores: no hay memoria de presets individual. Conserva los archivos locales al reabrir el Set.","Twelve numeric slots per Layer, mapped to each tool’s own manifest labels and ranges.":"Doce controles numéricos por capa, con nombres y rangos definidos por el manifest de la herramienta.","Use the single reset beside a parameter for that control only. DEFAULT restores the loaded tool’s manifest defaults.":"El reset junto a un parámetro afecta solo a ese control. DEFAULT restaura los valores por defecto del manifest de la herramienta cargada.","Up to four tool-defined colors, independent opacity and per-Layer blend mode.":"Hasta cuatro colores definidos por la herramienta, opacidad independiente y modo de mezcla por capa.","Color opacity is a native host control and does not consume P01–P12. Missing host opacity keeps the standalone tool behaviour unchanged.":"La opacidad es un control nativo del host y no ocupa P01–P12. Sin ese control, la herramienta standalone mantiene su comportamiento.","Velocity becomes the modulation peak. Attack rises to that peak, then release returns automatically to zero.":"Velocity establece el pico de modulación. Attack lo alcanza y Release vuelve automáticamente a cero.","The incoming 0–127 value becomes the target. Attack smooths upward movement; release smooths downward movement.":"El valor CC entrante (0–127) es el objetivo. Attack suaviza las subidas y Release las bajadas.","Refreshes the remote catalogue and compares it with the flat local":"Actualiza el catálogo remoto y lo compara con la biblioteca local","library. It does not download tools automatically.":": no descarga herramientas automáticamente.","Depending on state, the action becomes LOAD, UPDATE or DOWNLOAD. A dropdown selection alone never changes the running Layer.":"Según el estado, la acción es LOAD, UPDATE o DOWNLOAD. Elegir en el menú nunca cambia la capa activa por sí solo.","Queues only MISSING and OUTDATED catalogue tools. CURRENT entries are left untouched; local-only fixtures remain local.":"Añade solo herramientas MISSING y OUTDATED. Las CURRENT no cambian; las locales siguen siendo locales.","A ready local Node host, a supported installed Chromium browser and compatible Canvas/WebGL support are required.":"Se requiere un host Node local listo, Chromium compatible y soporte Canvas/WebGL.","Mappings start unassigned. Choose the MIDI input and channel, then a slot source and NOTE/CC ID. NONE unassigns a slot. Amount sets the contribution; attack/release shape its response. Assignments are Layer-specific and saved with the Set; the functional Live controls keep their automation identities.":"Las asignaciones empiezan vacías. Selecciona entrada y canal MIDI, fuente del espacio e ID NOTE/CC. NONE elimina una asignación. Amount determina la intensidad y Attack/Release modelan la respuesta. Cada capa guarda sus asignaciones con el Set; los controles Live conservan sus identidades de automatización.","RENDER launches the localhost compositor in an external Chromium app window. Live state reaches one compositor SSE connection, then the five tool iframes through":"RENDER inicia el compositor localhost en una ventana Chromium externa. El estado de Live llega mediante una conexión SSE al compositor y luego a los cinco iframes por","Actual / target FPS shows completed visual frames. The display-only dial fills up to the target and cannot be edited. FRAME CADENCE reports the observed interval between completed frames in milliseconds, not GPU execution time. PREVIEW shows the effective buffer dimensions.":"Actual / target FPS muestra fotogramas visuales completados. El dial solo indica el valor hasta el objetivo y no se puede editar. FRAME CADENCE mide el intervalo observado entre fotogramas terminados, no el tiempo de GPU. PREVIEW muestra el tamaño real del búfer.","AUTO follows browser / display-driven cadence; its target is estimated (~). Fixed settings request a maximum of 30 or 60 FPS across the hosted tools and compositor. Actual FPS can be lower with heavier tools.":"AUTO sigue la cadencia del navegador/pantalla y su objetivo es estimado (~). Los ajustes fijos solicitan un máximo de 30 o 60 FPS en herramientas y compositor. Los FPS reales pueden ser menores con herramientas exigentes.","AUTO keeps window-dependent rendering. Fixed presets control pixel workload: 1280 × 720, 1920 × 1080, 2560 × 1440 or 3840 × 2160 in a 16:9 window. Other window shapes keep their framing and fill the window, using a buffer that fits within the preset dimensions. PREVIEW reports the actual size; Retina does not multiply a fixed preset.":"AUTO adapta el renderizado a la ventana. Los presets fijos limitan la carga de píxeles a 1280 × 720, 1920 × 1080, 2560 × 1440 o 3840 × 2160 en formato 16:9. Otros formatos conservan el encuadre y llenan la ventana con un búfer dentro del límite del preset. PREVIEW muestra el tamaño real; Retina no multiplica un preset fijo.","The full composition scales to the RENDER window without zooming or cropping when RES changes. Settings survive closing and reopening RENDER and are saved with the Live Set. A new unconfigured device starts from AUTO / AUTO. If a buffer is unsupported, INDEX reports the error and restores the preceding selection.":"La composición se adapta a RENDER sin zoom ni recorte al cambiar RES. Los ajustes se mantienen al cerrar y reabrir RENDER y se guardan con el Live Set. Un dispositivo nuevo empieza en AUTO / AUTO. Si el búfer no es compatible, INDEX avisa y restaura la selección anterior.","Keep the complete folder together, load a local tool, and confirm Chromium is installed. RENDER opens an isolated app-style Chromium window; HELP uses the normal browser. Missing tool/module/font errors need the exact Console message and package version. CHECK refreshes metadata without replacing HTML; UPDATE explicitly downloads a selected tool.":"Mantén junta la carpeta completa, carga una herramienta local y verifica Chromium. RENDER abre una ventana Chromium aislada; HELP usa el navegador normal. Ante errores de herramientas, módulos o fuentes ausentes, guarda el mensaje exacto de consola y versión del paquete. CHECK actualiza metadatos sin sustituir HTML; UPDATE descarga explícitamente la herramienta elegida.","The library compares the files installed locally with the INDEX catalogue. These labels explain each possible result:":"La biblioteca compara los archivos instalados localmente con el catálogo INDEX. Estas etiquetas explican los posibles resultados:","Core":"Core","Mix it up":"Mézclalo","Shape the signal":"Da forma a la señal","Map it":"Mapéalo","Time behaviours?":"¿Comportamientos temporales?","Never heard of them? They can get pretty interesting.":"¿Nunca has oído hablar de ellos? Pueden resultar muy interesantes.","Send audio through the device, or feed it from another track using the SC panel.":"Envía audio a través del dispositivo o desde otra pista mediante el panel SC.","C can combine A and B, add a little chaos, or bring mathematical constants into the mix.":"C puede combinar A y B, añadir algo de caos o incorporar constantes matemáticas a la mezcla.","Fine-tune the incoming signals and sculpt the modulation curves with plenty of control.":"Ajusta con precisión las señales entrantes y esculpe las curvas de modulación con amplio control.","A, B and C each have a native 1+7 mapper. Go wild.":"A, B y C tienen cada uno un mapeador nativo 1+7. Da rienda suelta a tu creatividad.","A follows audio intensity from the main input or the external sidechain. Open AUDIO to shape its envelope.":"A sigue la intensidad del audio de la entrada principal o de la sidechain externa. Abre AUDIO para dar forma a su envolvente.","Open SC to choose an external source and channel, then set Mix between the main and external analysis inputs.":"Abre SC para elegir una fuente y un canal externos; ajusta Mix entre la entrada principal y la externa para el análisis.","B develops with the duration of recognized contact. Open TIME for its window, growth, behaviours, hold and decay.":"B evoluciona con la duración del contacto reconocido. Abre TIME para ajustar ventana, crecimiento, comportamientos, hold y decay.","C combines the final A and B signals, with its own scope and mapper. The Core overlays A in green, B in orange and C in yellow.":"C combina las señales finales A y B con su propio osciloscopio y mapeador. Core superpone A en verde, B en naranja y C en amarillo.","The device includes a short on-screen message to help you understand the selected behaviour at a glance.":"El dispositivo muestra un breve mensaje para entender de un vistazo el comportamiento seleccionado.","SC activity":"Actividad SC","Open SC, choose the source track and channel, then use Mix to blend the main input (dry) with the external source (wet) for analysis. Check A in the Core while setting the blend.":"Abre SC, elige pista y canal de origen y usa Mix para combinar la entrada principal (dry) con la fuente externa (wet) para el análisis. Observa A en Core al ajustar la mezcla.","The SC button blinks even when the panel is closed when the device is on, an external route is valid and Mix is above zero. It indicates active routing, including when the source is silent. SC opens to the left of the Core; AUDIO, TIME and MIXED open independently to the right.":"El botón SC parpadea incluso con el panel cerrado cuando el dispositivo está encendido, hay una ruta externa válida y Mix es mayor que cero. Indica routing activo aunque la fuente esté en silencio. SC se abre a la izquierda de Core; AUDIO, TIME y MIXED se abren por separado a la derecha.","Open L1–L5, choose a tool and check its library status. Press LOAD, UPDATE or DOWNLOAD to use it; selecting the name alone does not change the running Layer.":"Abre L1–L5, elige una herramienta y comprueba su estado. Pulsa LOAD, UPDATE o DOWNLOAD para usarla; seleccionar el nombre no cambia el Layer activo.","Open the online HELP in your normal browser. The current device button opens the BeerBelgio homepage while the product guide is being prepared.":"Abre la HELP online en tu navegador habitual. El botón actual abre la página principal de BeerBelgio mientras se prepara la guía del producto.","RENDER uses a private browser session for each instance. It is designed to close its rendering processes when you close the output, toggle RENDER, switch Live Sets or quit Live. If the output remains open, see Troubleshooting.":"RENDER usa una sesión privada del navegador por instancia. Está diseñado para cerrar sus procesos al cerrar la salida, desactivar RENDER, cambiar de Live Set o salir de Live. Si la salida sigue abierta, consulta Resolución de problemas.","Contact begins with duration: TIME GATE sets how long the signal must stay above the AUDIO Threshold before B starts growing. Gate spans 0–2000 ms in 5 ms steps; 0 starts immediately. AUDIO Threshold sets the separate amplitude condition after Gain/Rise/Fall and before Audio Amount (default 5%; effective range 0.1–95%).":"El contacto empieza por la duración: TIME GATE define cuánto tiempo debe permanecer la señal por encima de AUDIO Threshold antes de que B crezca. Gate abarca 0–2000 ms en pasos de 5 ms; 0 inicia de inmediato. AUDIO Threshold define por separado la condición de amplitud después de Gain/Rise/Fall y antes de Audio Amount (valor inicial 5 %; rango efectivo 0,1–95 %).","C reads the final A and B outputs without feeding back into them. It has an independent trace and mapper, updated on the existing nominal 5 ms tick.":"C lee las salidas finales A y B sin realimentarlas. Tiene una traza y un mapeador independientes, actualizados en el tick nominal existente de 5 ms.","CONSEQUENCE OF TIME is in testing and is not publicly distributed. No installation package or download is offered here.":"CONSEQUENCE OF TIME está en pruebas y no se distribuye públicamente. Aquí no se ofrece ningún paquete de instalación ni descarga.","87 functional Live controls keep their identities, plus one hidden performance gauge. Each of the five Layers exposes up to 12 numeric slots, with independent color opacity and visibility controls.":"Los 87 controles funcionales de Live conservan su identidad, junto a un indicador de rendimiento oculto. Cada uno de los cinco Layers ofrece hasta 12 slots numéricos y controles independientes de opacidad de color y visibilidad.","The Live parameter remains the automation and external modulation target. Internal Note/CC temporarily owns the final value of an assigned slot; choose NONE to return it to native editing.":"El parámetro de Live sigue siendo el destino de automatización y modulación externa. Note/CC interno controla temporalmente el valor final de un slot asignado; elige NONE para volver a la edición nativa.","Choose NONE to return an internally mapped slot to native editing. Check its final value and destination response after changing assignment.":"Elige NONE para devolver un slot asignado internamente a la edición nativa. Comprueba el valor final y la respuesta del destino después de cambiar la asignación.","Up to four manifest-defined colors per Layer. Edit them with the native picker or #RRGGBB text; unused slots display UNUSED.":"Hasta cuatro colores definidos por el manifiesto por Layer. Edítalos con el selector nativo o texto #RRGGBB; los slots sin usar muestran UNUSED.","Open one Layer editor; click its control again to close it.":"Abre un editor de Layer; pulsa de nuevo su control para cerrarlo.","Include or exclude each Layer independently from editor visibility.":"Incluye o excluye cada Layer con independencia de la visibilidad de su editor.","Open the INDEX HTML project website.":"Abre el sitio web del proyecto INDEX HTML.","Toggle one dedicated Chromium output owned by this Bridge instance.":"Activa o desactiva una salida Chromium dedicada a esta instancia Bridge.","Installation metadata or resolved local file is absent.":"Faltan los metadatos de instalación o el archivo local resuelto.","Installed entry absent from the remote catalogue, with an existing local file.":"La entrada instalada no figura en el catálogo remoto, pero existe su archivo local.","Local file exists and installation version differs from catalogue version.":"Existe el archivo local y la versión instalada difiere de la del catálogo.","Local file exists and installation version equals catalogue version.":"Existe el archivo local y la versión instalada coincide con la del catálogo."},"fr":{"Support":"Assistance","Quick start":"Démarrage rapide","Troubleshooting":"Dépannage","Under the hood":"Sous le capot","Layers":"Couches","Params":"Paramètres","Parameters":"Paramètres","Color":"Couleur","Library":"Bibliothèque","Performance":"Performances","Time":"Temps","Mapping":"Mappage","REPORT AN ISSUE":"SIGNALER UN PROBLÈME","Report an issue or get in touch.":"Signaler un problème ou me contacter.","Having trouble with INDEX HTML BRIDGE? Get in touch.":"Un problème avec INDEX HTML BRIDGE ? Contactez-moi.","Having trouble with CONSEQUENCE OF TIME? Get in touch.":"Un problème avec CONSEQUENCE OF TIME ? Contactez-moi.","Send some audio":"Envoyer un signal audio","Shape the audio-responsive signal A.":"Façonnez le signal A réactif à l’audio.","Audio source":"Source audio","Use the main track input or select an external sidechain. Check routing when nothing moves.":"Utilisez l’entrée de la piste ou une sidechain externe. Si rien ne bouge, vérifiez le routage.","Adjust incoming level before the signal is analyzed.":"Réglez le niveau d’entrée avant l’analyse.","Set how quickly signal A reacts to increasing and decreasing audio intensity. These controls do not modify B Attack, Hold or Decay.":"Réglez la vitesse de réaction de A à la hausse et à la baisse de l’intensité. Cela ne modifie pas Attack, Hold ni Decay de B.","Adjust the amount applied to normalized A. It is not the contact threshold used by the time engine.":"Réglez l’intensité appliquée à A normalisé. Ce n’est pas le seuil de contact du moteur temporel.","Build a time-driven signal B from recognized contact.":"Construisez le signal temporel B à partir du contact détecté.","Contact threshold":"Seuil de contact","Choose BEATS (musical tempo) or TIME (elapsed time) as the accumulation window; the two modes retain separate values.":"Choisissez BEATS (tempo musical) ou TIME (temps écoulé) comme fenêtre d’accumulation ; les deux modes conservent leurs valeurs propres.","Set initial signal level and range of movement.":"Définissez le niveau initial et l’amplitude du mouvement du signal.","Attack smooths growth, Hold keeps the value after contact is lost, Decay returns B toward zero.":"Attack lisse la montée, Hold maintient la valeur après la perte de contact et Decay ramène B vers zéro.","Pure time evolution. Time Amount has no effect in CLEAN.":"Évolution temporelle pure. Time Amount n’a aucun effet en mode CLEAN.","Changes movement range in response to intensity.":"Modifie l’amplitude du mouvement selon l’intensité.","Changes accumulation speed in response to intensity.":"Modifie la vitesse d’accumulation selon l’intensité.","Adds signal-dependent irregular fluctuations.":"Ajoute des fluctuations irrégulières dépendant du signal.","May produce a descending positive curve, not negative output; transitions can be abrupt.":"Peut produire une courbe positive descendante, et non une sortie négative ; les transitions peuvent être abruptes.","Can pause time progress when intensity meets its condition.":"Peut suspendre l’évolution temporelle lorsque la condition d’intensité est remplie.","Quantizes the time signal into discrete steps.":"Quantifie le signal temporel en paliers distincts.","Combines speed changes and irregular fluctuations. Time Amount adjusts each active behavior, not the basic B Depth.":"Combine changements de vitesse et fluctuations irrégulières. Time Amount règle chaque comportement actif, pas la valeur B Depth de base.","Mod works as relative modulation around a parameter base value. Remote takes exclusive control of its destination. These are native Ableton behaviors.":"Mod module relativement à la valeur de base du paramètre. Remote prend le contrôle exclusif de la destination. Ce sont des comportements natifs d’Ableton.","Save & Reload":"Sauvegarder et rouvrir","After mapping, verify actual modulation after saving and reopening the Live Set — not only that the destination name persists.":"Après le mappage, sauvegardez puis rouvrez le Live Set pour vérifier la modulation effective, pas seulement la persistance du nom de destination.","Distribution note":"Note sur la distribution","Choose a separate source for audio analysis.":"Choisissez une source distincte pour l’analyse audio.","Main audio":"Audio principal","External sidechain":"Sidechain externe","Common checks for signal, timing and mapping.":"Vérifications courantes du signal, du temps et du mappage.","No signal movement":"Aucun mouvement du signal","Confirm that audio is present, inspect source and routing, increase Gain as appropriate, and check the contact threshold and B Depth.":"Vérifiez la présence d’audio, la source et le routage ; ajustez Gain, le seuil de contact et B Depth.","A moves but B does not":"A bouge, mais pas B","Check the threshold and Tolerance, the Window, Growth, B Start/Depth and whether sufficient contact time has accumulated.":"Vérifiez le seuil, Tolerance, Window, Growth, B Start/Depth et l’accumulation d’une durée de contact suffisante.","Mapping looks static":"Le mappage semble statique","In Mod mode, the base knob may stay at its set value while modulation operates. Check the destination response, not only the knob position.":"En mode Mod, le potentiomètre de base peut rester fixe pendant la modulation. Vérifiez la réaction de la destination, pas seulement le potentiomètre.","A: amplitude response":"A : réponse en amplitude","The envelope follower translates the level of the input signal into a continuous normalized modulation output.":"Le suiveur d’enveloppe transforme le niveau d’entrée en une modulation continue et normalisée.","B: duration response":"B : réponse à la durée","Contact recognition drives a separate time engine. Window, Growth, Accel, Hold, Decay and Behavior change the shape of B.":"La détection de contact pilote un moteur temporel distinct. Window, Growth, Accel, Hold, Decay et Behavior façonnent B.","Audio transparency":"Transparence audio","Shape it":"Le façonner","Open PARAMETERS, COLORS & BLEND and MIDI MAPPING in any combination.":"Ouvrez PARAMETERS, COLORS & BLEND et MIDI MAPPING selon vos besoins.","Render live":"Générer en direct","RENDER opens the external Chromium compositor. Your five Layers are combined there.":"RENDER ouvre le compositeur externe Chromium, où les cinq couches sont combinées.","Five independent visual slots, composed from L1 upward. Effects process only what sits below them.":"Cinq couches visuelles indépendantes, composées à partir de L1. Les effets traitent uniquement les couches inférieures.","One editor, five layers":"Un éditeur, cinq couches","Tool loading":"Chargement d’outil","Generator vs effect":"Générateur ou effet","Remembered per layer":"Mémoire par couche","Native Live parameters":"Paramètres Live natifs","Reset & defaults":"Réinitialisation et valeurs par défaut","Effective values":"Valeurs effectives","Automation stays yours":"L’automation reste intacte","Colors & Blend":"Couleurs et fusion","Effect Layers do not use generator blend in the same way: their shader processes the lower composite directly.":"Les couches d’effet n’utilisent pas le mode de fusion comme les générateurs : leur shader traite directement la composition inférieure.","MIDI Mapping":"Mappage MIDI","Map NOTE or CC directly onto P01–P12 with amount and envelope/smoothing controls.":"Assignez NOTE ou CC directement à P01–P12 avec intensité et enveloppe/lissage.","Status":"État","Selected tool":"Outil sélectionné","Requirements":"Prérequis","Live output":"Sortie en direct","Live Render Performance":"Performances du rendu live","Automatic panel":"Panneau automatique","Read the monitor":"Lire le moniteur","Same view, different quality":"Même cadrage, qualité différente","The useful failure boundaries, current limitations and what not to expect from this build.":"Les principaux cas d’échec, les limites actuelles et ce que cette version ne fait pas.","Browser or missing resources":"Navigateur ou ressources manquantes","Only if you care: how Max, Node and Chromium divide the work.":"Pour aller plus loin : la répartition du travail entre Max, Node et Chromium.","No Jitter renderer":"Pas de rendu Jitter","INDEX HTML stays browser-native. The fundamental split is simple: Max decides what happens; the browser decides how to draw it.":"INDEX HTML reste natif du navigateur : Max décide de ce qui se passe ; le navigateur décide comment l’afficher.","Open one Layer editor at a time. Layer visibility is independent from whether its editor is open.":"Ouvrez un éditeur de couche à la fois. La visibilité d’une couche ne dépend pas de l’ouverture de son éditeur.","Choosing a tool in the dropdown only selects it. Press LOAD to use the selection. A new LOAD restores manifest defaults. Keep tools/ and the complete device folder together; local INDEX_TOOL RC2 and legacy SKETCH_TOOL files work offline.":"Le menu ne fait que sélectionner l’outil : appuyez sur LOAD. Un nouveau LOAD restaure les valeurs par défaut du manifeste. Conservez tools/ avec le dossier complet ; INDEX_TOOL RC2 et les anciens SKETCH_TOOL fonctionnent hors ligne.","Generators draw their own canvas. Effects receive the composite of the Layers beneath them and process that result.":"Les générateurs dessinent sur leur propre canvas. Les effets traitent la composition des couches inférieures.","Each Layer remembers its section visibility. Saving a Live Set also stores the loaded tools, native values, HEX, mappings and device settings. Changing a tool resets its values: there is no separate preset memory for every tool. Keep the local tool files available when reopening a Set.":"Chaque couche mémorise ses sections ouvertes. Le Live Set conserve outils chargés, valeurs natives, HEX, mappages et réglages. Changer d’outil rétablit ses valeurs : pas de mémoire de preset par outil. Conservez les fichiers locaux pour rouvrir le Set.","Twelve numeric slots per Layer, mapped to each tool’s own manifest labels and ranges.":"Douze emplacements numériques par couche, avec noms et plages définis par le manifeste de l’outil.","Use the single reset beside a parameter for that control only. DEFAULT restores the loaded tool’s manifest defaults.":"Le reset près d’un paramètre n’agit que sur ce contrôle. DEFAULT restaure les valeurs du manifeste de l’outil chargé.","Up to four tool-defined colors, independent opacity and per-Layer blend mode.":"Jusqu’à quatre couleurs définies par l’outil, opacité indépendante et mode de fusion par couche.","Color opacity is a native host control and does not consume P01–P12. Missing host opacity keeps the standalone tool behaviour unchanged.":"L’opacité est un contrôle natif de l’hôte, sans utiliser P01–P12. En son absence, le comportement autonome de l’outil reste inchangé.","Velocity becomes the modulation peak. Attack rises to that peak, then release returns automatically to zero.":"La vélocité définit le pic de modulation. Attack l’atteint, puis Release revient automatiquement à zéro.","The incoming 0–127 value becomes the target. Attack smooths upward movement; release smooths downward movement.":"La valeur CC entrante (0–127) devient la cible. Attack lisse la montée et Release la descente.","Refreshes the remote catalogue and compares it with the flat local":"Actualise le catalogue distant et le compare à la bibliothèque locale","library. It does not download tools automatically.":": aucun outil n’est téléchargé automatiquement.","Depending on state, the action becomes LOAD, UPDATE or DOWNLOAD. A dropdown selection alone never changes the running Layer.":"Selon l’état, l’action devient LOAD, UPDATE ou DOWNLOAD. Choisir dans le menu ne change jamais la couche active à lui seul.","Queues only MISSING and OUTDATED catalogue tools. CURRENT entries are left untouched; local-only fixtures remain local.":"Met en file uniquement les outils MISSING et OUTDATED. Les CURRENT restent inchangés et les éléments locaux restent locaux.","A ready local Node host, a supported installed Chromium browser and compatible Canvas/WebGL support are required.":"Il faut un hôte Node local prêt, un navigateur Chromium compatible et Canvas/WebGL.","Mappings start unassigned. Choose the MIDI input and channel, then a slot source and NOTE/CC ID. NONE unassigns a slot. Amount sets the contribution; attack/release shape its response. Assignments are Layer-specific and saved with the Set; the functional Live controls keep their automation identities.":"Les mappages sont initialement vides. Choisissez l’entrée, le canal MIDI, la source d’emplacement et l’ID NOTE/CC. NONE supprime une assignation. Amount règle la contribution, Attack/Release la réponse. Les assignations sont propres à chaque couche et sauvegardées dans le Set ; les contrôles Live conservent leurs identités d’automation.","RENDER launches the localhost compositor in an external Chromium app window. Live state reaches one compositor SSE connection, then the five tool iframes through":"RENDER lance le compositeur localhost dans une fenêtre Chromium externe. L’état Live passe par une connexion SSE vers le compositeur, puis vers les cinq iframes grâce à","Actual / target FPS shows completed visual frames. The display-only dial fills up to the target and cannot be edited. FRAME CADENCE reports the observed interval between completed frames in milliseconds, not GPU execution time. PREVIEW shows the effective buffer dimensions.":"Actual / target FPS affiche les images visuelles terminées. Le potentiomètre est purement indicatif, se remplit jusqu’à la cible et ne peut pas être modifié. FRAME CADENCE indique l’intervalle entre images terminées en millisecondes, pas le temps GPU. PREVIEW affiche la taille effective du tampon.","AUTO follows browser / display-driven cadence; its target is estimated (~). Fixed settings request a maximum of 30 or 60 FPS across the hosted tools and compositor. Actual FPS can be lower with heavier tools.":"AUTO suit la cadence du navigateur/écran ; sa cible est estimée (~). Les réglages fixes demandent un maximum de 30 ou 60 FPS pour outils et compositeur. Les FPS réels peuvent être inférieurs avec des outils plus lourds.","AUTO keeps window-dependent rendering. Fixed presets control pixel workload: 1280 × 720, 1920 × 1080, 2560 × 1440 or 3840 × 2160 in a 16:9 window. Other window shapes keep their framing and fill the window, using a buffer that fits within the preset dimensions. PREVIEW reports the actual size; Retina does not multiply a fixed preset.":"AUTO adapte le rendu à la fenêtre. Les préréglages fixes limitent la charge en pixels à 1280 × 720, 1920 × 1080, 2560 × 1440 ou 3840 × 2160 en 16:9. Les autres formats conservent le cadrage et remplissent la fenêtre avec un tampon dans les limites du préréglage. PREVIEW affiche la taille réelle ; Retina ne multiplie pas un préréglage fixe.","The full composition scales to the RENDER window without zooming or cropping when RES changes. Settings survive closing and reopening RENDER and are saved with the Live Set. A new unconfigured device starts from AUTO / AUTO. If a buffer is unsupported, INDEX reports the error and restores the preceding selection.":"La composition entière s’adapte à RENDER sans zoom ni recadrage quand RES change. Les réglages survivent à la fermeture et sont enregistrés dans le Live Set. Un nouveau device démarre en AUTO / AUTO. Si un tampon n’est pas pris en charge, INDEX signale l’erreur et restaure le choix précédent.","Keep the complete folder together, load a local tool, and confirm Chromium is installed. RENDER opens an isolated app-style Chromium window; HELP uses the normal browser. Missing tool/module/font errors need the exact Console message and package version. CHECK refreshes metadata without replacing HTML; UPDATE explicitly downloads a selected tool.":"Conservez le dossier complet, chargez un outil local et vérifiez Chromium. RENDER ouvre une fenêtre Chromium isolée, HELP le navigateur habituel. En cas d’outil/module/police manquant, conservez le message exact de console et la version du paquet. CHECK actualise les métadonnées sans remplacer le HTML ; UPDATE télécharge explicitement l’outil choisi.","The library compares the files installed locally with the INDEX catalogue. These labels explain each possible result:":"La bibliothèque compare les fichiers installés localement au catalogue INDEX. Ces libellés expliquent les résultats possibles:","Core":"Core","Mix it up":"Mélangez","Shape the signal":"Sculptez le signal","Map it":"Assignez","Time behaviours?":"Comportements temporels ?","Never heard of them? They can get pretty interesting.":"Vous ne les connaissez pas ? Ils peuvent devenir très intéressants.","Send audio through the device, or feed it from another track using the SC panel.":"Faites passer de l’audio dans le device ou alimentez-le depuis une autre piste avec le panneau SC.","C can combine A and B, add a little chaos, or bring mathematical constants into the mix.":"C peut combiner A et B, ajouter un peu de chaos ou introduire des constantes mathématiques.","Fine-tune the incoming signals and sculpt the modulation curves with plenty of control.":"Ajustez finement les signaux entrants et sculptez les courbes de modulation avec de nombreux réglages.","A, B and C each have a native 1+7 mapper. Go wild.":"A, B et C disposent chacun d’un mapper natif 1+7. Lâchez-vous.","A follows audio intensity from the main input or the external sidechain. Open AUDIO to shape its envelope.":"A suit l’intensité audio de l’entrée principale ou de la sidechain externe. Ouvrez AUDIO pour façonner son enveloppe.","Open SC to choose an external source and channel, then set Mix between the main and external analysis inputs.":"Ouvrez SC pour choisir une source et un canal externes, puis réglez Mix entre les entrées principale et externe pour l’analyse.","B develops with the duration of recognized contact. Open TIME for its window, growth, behaviours, hold and decay.":"B évolue avec la durée du contact reconnu. Ouvrez TIME pour sa fenêtre, sa croissance, ses comportements, hold et decay.","C combines the final A and B signals, with its own scope and mapper. The Core overlays A in green, B in orange and C in yellow.":"C combine les signaux finaux A et B, avec son propre scope et mapper. La Core superpose A en vert, B en orange et C en jaune.","The device includes a short on-screen message to help you understand the selected behaviour at a glance.":"Un bref message à l’écran permet de comprendre d’un coup d’œil le comportement sélectionné.","SC activity":"Activité SC","Open SC, choose the source track and channel, then use Mix to blend the main input (dry) with the external source (wet) for analysis. Check A in the Core while setting the blend.":"Ouvrez SC, choisissez la piste et le canal source, puis utilisez Mix pour mélanger l’entrée principale (dry) et la source externe (wet) pour l’analyse. Observez A dans la Core pendant le réglage.","The SC button blinks even when the panel is closed when the device is on, an external route is valid and Mix is above zero. It indicates active routing, including when the source is silent. SC opens to the left of the Core; AUDIO, TIME and MIXED open independently to the right.":"Le bouton SC clignote même panneau fermé lorsque le device est actif, qu’une route externe est valide et que Mix dépasse zéro. Il indique un routage actif même si la source est silencieuse. SC s’ouvre à gauche de la Core ; AUDIO, TIME et MIXED s’ouvrent indépendamment à droite.","Open L1–L5, choose a tool and check its library status. Press LOAD, UPDATE or DOWNLOAD to use it; selecting the name alone does not change the running Layer.":"Ouvrez L1–L5, choisissez un outil et vérifiez son état. Utilisez LOAD, UPDATE ou DOWNLOAD ; sélectionner le nom seul ne change pas le Layer actif.","Open the online HELP in your normal browser. The current device button opens the BeerBelgio homepage while the product guide is being prepared.":"Ouvrez la HELP en ligne dans votre navigateur habituel. Le bouton actuel ouvre l’accueil BeerBelgio pendant la préparation du guide du produit.","RENDER uses a private browser session for each instance. It is designed to close its rendering processes when you close the output, toggle RENDER, switch Live Sets or quit Live. If the output remains open, see Troubleshooting.":"RENDER utilise une session privée du navigateur par instance. Ses processus doivent se fermer à la fermeture de la sortie, à la désactivation de RENDER, au changement de Live Set ou à la fermeture de Live. Si la sortie reste ouverte, consultez Dépannage.","Contact begins with duration: TIME GATE sets how long the signal must stay above the AUDIO Threshold before B starts growing. Gate spans 0–2000 ms in 5 ms steps; 0 starts immediately. AUDIO Threshold sets the separate amplitude condition after Gain/Rise/Fall and before Audio Amount (default 5%; effective range 0.1–95%).":"Le contact commence par la durée : TIME GATE définit combien de temps le signal doit rester au-dessus d’AUDIO Threshold avant que B croisse. Gate va de 0 à 2000 ms par pas de 5 ms ; 0 démarre immédiatement. AUDIO Threshold fixe séparément la condition d’amplitude après Gain/Rise/Fall et avant Audio Amount (défaut 5 % ; plage effective 0,1–95 %).","C reads the final A and B outputs without feeding back into them. It has an independent trace and mapper, updated on the existing nominal 5 ms tick.":"C lit les sorties finales A et B sans rétroaction. Sa trace et son mapper indépendants sont actualisés au tick nominal existant de 5 ms.","CONSEQUENCE OF TIME is in testing and is not publicly distributed. No installation package or download is offered here.":"CONSEQUENCE OF TIME est en test et n’est pas distribué publiquement. Aucun paquet d’installation ni téléchargement n’est proposé ici.","87 functional Live controls keep their identities, plus one hidden performance gauge. Each of the five Layers exposes up to 12 numeric slots, with independent color opacity and visibility controls.":"Les 87 contrôles fonctionnels Live conservent leur identité, avec un indicateur de performance masqué en plus. Chacun des cinq Layers offre jusqu’à 12 emplacements numériques et des contrôles indépendants d’opacité des couleurs et de visibilité.","The Live parameter remains the automation and external modulation target. Internal Note/CC temporarily owns the final value of an assigned slot; choose NONE to return it to native editing.":"Le paramètre Live reste la cible de l’automation et de la modulation externe. Note/CC interne contrôle temporairement la valeur finale d’un emplacement assigné ; NONE rétablit l’édition native.","Choose NONE to return an internally mapped slot to native editing. Check its final value and destination response after changing assignment.":"Choisissez NONE pour rendre l’édition native à un emplacement assigné en interne. Vérifiez sa valeur finale et la réponse de la cible après toute réassignation.","Up to four manifest-defined colors per Layer. Edit them with the native picker or #RRGGBB text; unused slots display UNUSED.":"Jusqu’à quatre couleurs définies par le manifeste par Layer. Modifiez-les avec le sélecteur natif ou le texte #RRGGBB ; les emplacements inutilisés affichent UNUSED.","Open one Layer editor; click its control again to close it.":"Ouvrez un éditeur de Layer ; cliquez à nouveau sur son contrôle pour le fermer.","Include or exclude each Layer independently from editor visibility.":"Incluez ou excluez chaque Layer indépendamment de la visibilité de son éditeur.","Open the INDEX HTML project website.":"Ouvrez le site du projet INDEX HTML.","Toggle one dedicated Chromium output owned by this Bridge instance.":"Activez ou désactivez la sortie Chromium dédiée à cette instance Bridge.","Installation metadata or resolved local file is absent.":"Les métadonnées d’installation ou le fichier local résolu sont absents.","Installed entry absent from the remote catalogue, with an existing local file.":"L’entrée installée est absente du catalogue distant, mais son fichier local existe.","Local file exists and installation version differs from catalogue version.":"Le fichier local existe et la version installée diffère de celle du catalogue.","Local file exists and installation version equals catalogue version.":"Le fichier local existe et la version installée correspond au catalogue."}};
const supported=['en','it','de','es','fr'];
const storeKey='b4m4l.language';
const noticePrefix='b4m4l.translation-notice.';
const shownThisDocument=new Set();
const nav=()=>{try{return new URLSearchParams(location.search).get('lang')}catch(e){return null}};
const load=()=>{try{return localStorage.getItem(storeKey)}catch(e){try{return sessionStorage.getItem(storeKey)}catch(e2){return null}}};
let locale=supported.includes(nav())?nav():supported.includes(load())?load():'en';
const original=new WeakMap();
function translate(node){
 if(!node||node.nodeType!==3||!node.parentNode)return;
 const parent=node.parentNode;
 if(parent.closest&&parent.closest('script,style,code,pre,textarea,svg,[data-no-translate]'))return;
 const src=original.has(node)?original.get(node):node.nodeValue;
 if(!original.has(node))original.set(node,src);
 const trimmed=src.trim();if(!trimmed)return;
 const dict=translations[locale]||{};
 const translated=dict[trimmed]||trimmed;
 const left=src.match(/^\s*/)?.[0]||'',right=src.match(/\s*$/)?.[0]||'';
 const next=left+translated+right;
 if(node.nodeValue!==next)node.nodeValue=next;
}
function translateRoot(root){
 if(!root)return;
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
 let n;while((n=walker.nextNode()))translate(n);
}
function translateHelp(){
 // Only HELP content is translated. Homepage, device overview, requirements, changelog and privacy stay English.
 document.querySelectorAll('.hero,.quick-start,.manual').forEach(root=>{root.lang=locale;translateRoot(root)});
}
function links(){
 document.querySelectorAll('a[href]').forEach(a=>{
  const value=a.getAttribute('href');
  if(!value||value.startsWith('mailto:')||value.startsWith('#')||value.startsWith('javascript:')||value.startsWith('http:')||value.startsWith('https:'))return;
  try{const url=new URL(value,location.href);if(url.protocol!=='file:'&&url.origin!==location.origin)return;
   if(locale==='en')url.searchParams.delete('lang');else url.searchParams.set('lang',locale);
   a.setAttribute('href',url.protocol==='file:'?url.href:(url.pathname+url.search+url.hash));
  }catch(e){}
 });
}
function updateSelect(){
 document.querySelectorAll('select[data-b4-language]').forEach(select=>{
  select.value=locale;
  const selected=select.selectedOptions?.[0]?.textContent||locale.toUpperCase();
  // Optical width in text em, with room for chevron.
  select.style.width='auto';
 });
}
function render(){
 // The overall site language is English; only the manual subsections have a different lang.
 document.documentElement.lang='en';
 updateSelect();translateHelp();links();
}
function popupOnce(){
 if(!['de','es','fr'].includes(locale))return;
 const dlg=document.getElementById('b4-translation-dialog');if(!dlg)return;
 const key=noticePrefix+locale;
 if(shownThisDocument.has(locale))return;shownThisDocument.add(locale);
 try{if(sessionStorage.getItem(key))return;sessionStorage.setItem(key,'1')}catch(e){}
 if(typeof dlg.showModal==='function')dlg.showModal();else dlg.setAttribute('open','');
}
function save(lang){
 if(!supported.includes(lang))return;
 locale=lang;
 try{localStorage.setItem(storeKey,lang)}catch(e){try{sessionStorage.setItem(storeKey,lang)}catch(e2){}}
 try{const u=new URL(location.href);if(lang==='en')u.searchParams.delete('lang');else u.searchParams.set('lang',lang);history.replaceState(history.state,'',u.href)}catch(e){}
 render();popupOnce();
}
document.querySelectorAll('select[data-b4-language]').forEach(s=>s.addEventListener('change',()=>save(s.value)));
document.querySelectorAll('[data-close-translation-dialog]').forEach(btn=>btn.addEventListener('click',()=>{const dlg=btn.closest('dialog');if(dlg?.close)dlg.close();else dlg?.removeAttribute('open')}));
const dlg=document.getElementById('b4-translation-dialog');
if(dlg)dlg.addEventListener('click',e=>{if(e.target===dlg)dlg.close?.()});
let pending=false;
const observer=new MutationObserver(muts=>{
 if(pending||!muts.some(m=>m.type==='childList'&&m.addedNodes.length))return;
 pending=true;queueMicrotask(()=>{pending=false;translateHelp();links()});
});
render();observer.observe(document.body,{subtree:true,childList:true});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',popupOnce,{once:true});else popupOnce();
})();
